// The things a crawler reads, checked against each other.
//
// None of this is game logic, and it is here anyway for one reason: every
// failure this catches is invisible. A page with no canonical still renders. A
// page missing from the sitemap still works. The site looks perfect and is
// quietly unfindable, and nobody notices for a month.
//
// The sitemap itself is generated by the Worker (src/index.js) and cannot be
// fetched from a plain static server, so these read its PAGES list out of the
// source and compare that against what the pages themselves claim. Same drift,
// caught the same way — and it is the exact drift that had already happened:
// tiles.html shipped with a canonical and was never added to the list.

import { test, assert, eq, suite } from "./harness.js";
// The languages the site actually ships, from the module that decides it.
// Listed here instead, this guard would go stale the day a third one lands —
// which is the same drift it exists to catch, one level up.
import { LANGS } from "../js/lang.js";
// The page's OWN composition (#136). The build has a Python port of this;
// the guard below runs the real one and holds the port to it.
import { tileWords } from "../js/tilewords.js";

// Which copy of this suite is speaking. Stamped by tools/record_shell.py;
// report() compares it against the file on disk, so a stale module is caught
// even when the test count happens to match.
suite(import.meta.url, "57bf67f0");

const PUBLIC_PAGES = ["index", "game", "rulebook", "tiles", "credits", "ledger"];

// no-store: these assert about files on disk, and a cached copy of the file
// you are checking is how a fixed page keeps reporting the old fault.
const NO_STORE = { cache: "no-store" };

// AND no-store IS NOT ENOUGH ON ITS OWN. It governs the HTTP cache. It does not
// govern a SERVICE WORKER, whose fetch handler may answer from its own cache
// whatever the request asked for — and this site ships a cache-first shell that
// holds every page in this list. On a plain local server that never bites,
// because registerWorker() bails unless the host is https or localhost; on the
// deployed origin it does, and a suite reading its own shipped page can be
// handed the copy from the last deploy.
//
// A UNIQUE QUERY DEFEATS BOTH, because a cache is matched on the URL and this
// URL has never existed before. It cost a false RED — a reverted sabotage that
// kept reporting itself — and the false GREEN is the same mechanism pointed the
// other way: break the prose while a good copy is held, and the guard passes on
// a file that is broken on disk.
const stamp = Date.now() + "-" + Math.random().toString(36).slice(2);
const fresh = (path) => fetch(path + (path.includes("?") ? "&" : "?") + "fresh=" + stamp, NO_STORE);

const html = Object.fromEntries(
  await Promise.all(
    PUBLIC_PAGES.map(async (name) => [name, await fresh(`../${name}.html`).then((r) => r.text())]),
  ),
);
const worker = await fresh("../src/index.js").then((r) => r.text());

// Read out of the Worker source, the same way PAGES is. One flag, one place.
const SHIPPED = /export const SHIPPED\s*=\s*true/.test(worker);

const meta = (doc, name) => (doc.match(new RegExp(`name="${name}" content="([^"]*)"`)) || [])[1] || null;
const tag = (doc, re) => (doc.match(re) || [])[1] || null;

// The Worker builds its sitemap from these three constants; read them rather
// than restating the URLs, so the test cannot drift from the thing it checks.
const PREFIX = tag(worker, /const PREFIX = "(.*?)"/);
const ORIGIN = tag(worker, /const ORIGIN = "(.*?)"/);
const PAGES = tag(worker, /const PAGES = \[(.*?)\]/)
  .split(",")
  .map((p) => p.trim().replace(/^"|"$/g, ""));
const ROOT = `${ORIGIN}${PREFIX}/`;

// WHAT ENGLISH IS ALLOWED TO SURVIVE IN CHINESE MODE (#146).
//
// The topnav was English on four pages at once and no per-page check reached it,
// because the strings belong to the shared furniture rather than to any page —
// each page looked fine to whoever was working on it. So this renders the page
// in Chinese and asks what Latin is left, and every answer has to be one this
// list PERMITS. A guard that passes because nothing happened to match is the
// thing that let the bar sit there.
//
// WHICH PAGES, AND WHY NOT THE OTHER THREE — these are exclusions with reasons
// rather than convenience:
//   game.html      its bar is painted from the theme and its markup carries no
//                  unpainted English at all (measured: zero text nodes). Booting
//                  a whole game in an iframe inside this suite also destabilised
//                  the renderer repeatedly.
//   rulebook.html  already has its own guard — "the Chinese page carries no
//                  English prose" — and its glossary shows both scripts on
//                  purpose (真火符 True Fire Talisman).
//   credits.html   deliberately not translated; js/credits.js says so in full.
//                  Listing its thirty-odd English strings here would be
//                  transcribing a decision, not checking one.
// The shared bar those three DO carry is covered in data.test.js, page by page
// and in both directions, which is the check that would have caught #146.
const ALLOWED_LATIN = {
  // Every page: the switch names the language it would move TO, so "English"
  // on a Chinese page is correct and must never be "fixed".
  "*": ["English"],
  "index.html": [
    // The poster's own title shows both scripts, 三更：殭屍 over the English —
    // the same pairing the ledger's h1 and tabs use. The guard flagged this on
    // its first run because it was not listed, which is the list doing its job.
    "The Third Watch: The Jiangshi",
    // The talisman row pairs each Chinese name with an English label, the same
    // way the ledger's tabs do. Both halves are the design.
    "Start", "Rulebook", "The Tiles", "Ledger", "About me",
    // KNOWN GAP, NOT A DECISION. The lineage line under the poster is English
    // prose in both languages. The two game titles are proper nouns and should
    // stay, but "Inspired by" and "and" are not, and a Chinese reader gets an
    // English sentence. Raised with the owner; listed here so it is visible
    // rather than passing silently.
    "Inspired by", "Zombie in my Pocket", "(2007) and",
    "Betrayal at House on the Hill",
  ],
  "tiles.html": [],
  "ledger.html": [
    // 夜榜 The Ledger, and the tabs the owner asked to carry both halves.
    "The Ledger", "Burial", "Sealing", "Kills",
  ],
};

// Rendered, not read from the markup. A markup scan cannot answer this: rulebook
// replaces its whole main with a Chinese fragment and tiles rebuilds its gallery
// from the theme, so their sources are full of English that never reaches a
// Chinese reader. Measured — the markup view of rulebook.html has 339 Latin text
// nodes and its rendered Chinese view has the glossary and nothing else.
// PUTS THE PREFERENCE BACK. jitp:lang is shared with every other test in this
// browser, and leaving it on zh-TW made a later guard in stage.test.js render
// its page in Chinese and fail on a threshold written for English sentences.
// A test that changes global state and does not restore it does not fail — it
// makes a DIFFERENT test fail, somewhere else, for a reason that reads as
// unrelated.
async function latinInChinese(page) {
  const KEY = "jitp:lang";
  let had = null;
  try { had = localStorage.getItem(KEY); } catch { /* private mode */ }
  const f = document.createElement("iframe");
  f.style.cssText = "position:absolute;left:-99999px;top:0;border:0;width:375px;height:800px";
  try { localStorage.setItem(KEY, "zh-TW"); } catch { /* private mode */ }
  f.src = "../" + page;
  document.body.appendChild(f);
  try {
    await new Promise((res, rej) => {
      f.onload = res;
      setTimeout(() => rej(new Error(page + " never loaded")), 12000);
    });
    await new Promise((r) => setTimeout(r, 600));
    const d = f.contentDocument;
    const btn = d.querySelector("#btn-lang");
    for (let i = 0; i < 3 && !d.documentElement.lang.startsWith("zh"); i++) {
      if (btn) btn.click();
      await new Promise((r) => setTimeout(r, 450));
    }
    await new Promise((r) => setTimeout(r, 300));
    // PROVE IT IS ACTUALLY IN CHINESE. Everything below is an absence, and an
    // absence on an English page passes for the wrong reason.
    const lang = d.documentElement.lang;
    const seen = [];
    const w = d.createTreeWalker(d.body, NodeFilter.SHOW_TEXT);
    let n;
    while ((n = w.nextNode())) {
      const t = (n.nodeValue || "").replace(/\s+/g, " ").trim();
      if (!t || !/[A-Za-z]{2,}/.test(t)) continue;
      const el = n.parentElement;
      if (!el || !(el.offsetWidth || el.offsetHeight || el.getClientRects().length)) continue;
      seen.push(t);
    }
    return { lang, latin: [...new Set(seen)] };
  } finally {
    f.remove();
    try {
      if (had === null) localStorage.removeItem(KEY);
      else localStorage.setItem(KEY, had);
    } catch { /* private mode */ }
  }
}

test("chrome: only permitted English survives a Chinese page (#146)", async () => {
  for (const page of Object.keys(ALLOWED_LATIN).filter((k) => k !== "*")) {
    const { lang, latin } = await latinInChinese(page);
    assert(lang.startsWith("zh"),
      page + " never switched to Chinese (lang=" + lang + "), so finding no " +
      "English would have meant nothing");
    const allowed = ALLOWED_LATIN["*"].concat(ALLOWED_LATIN[page]);
    const strays = latin.filter((t) => !allowed.some((ok) => t.includes(ok)));
    eq(strays.length, 0,
      page + " renders English this list does not permit: " +
      JSON.stringify(strays.slice(0, 6)) + ". Either translate it, or add it to " +
      "ALLOWED_LATIN with a line saying why it is allowed to stay.");
    // And the page has to have been read at all.
    assert(latin.length > 0,
      page + " rendered no Latin whatsoever, not even the language switch — " +
      "the sweep walked an empty or unrendered document");
  }
});

// A NEWLINE BETWEEN TWO CHINESE CHARACTERS IS A SPACE (#144).
//
// HTML collapses a source newline and its indent into ONE RENDERED SPACE.
// Between English words that is the whole point and is invisible. Between two
// Chinese characters it is a space in the middle of a sentence, and the ledger's
// Chinese lede shipped that way: 伺服器上 重跑過一遍.
//
// THIS IS A RULE ABOUT THE LANGUAGE, NOT ABOUT THAT PARAGRAPH. Any Chinese
// written into markup has the same trap waiting, and the change that springs it
// is the most innocent one there is — re-wrapping a long line to fit a column.
// Nothing about the result looks wrong in the source.
//
// The test is "the line ends with a non-Latin character AND the next begins with
// one", which is wider than checking for CJK on both sides and deliberately so:
// the first version of this scan missed 一夜——\n不是, because an em dash is not a
// CJK codepoint while still being a place Chinese wants no space. A break
// between Chinese and LATIN is left alone — 需要\nJavaScript renders as
// "需要 JavaScript", which is the correct spacing.
const nonLatin = (ch) => !!ch && ch.codePointAt(0) > 0x7f;

test("seo: no Chinese sentence is broken across source lines (#144)", () => {
  let checked = 0;
  for (const name of PUBLIC_PAGES) {
    const lines = html[name].split("\n");
    let inComment = false;
    for (let i = 0; i < lines.length - 1; i++) {
      // Comments are not rendered, so a wrapped Chinese sentence inside one is
      // harmless. Flagging it would make this fire on prose nobody reads, which
      // is how a guard teaches people to skip past it.
      const line = lines[i];
      if (inComment) {
        if (line.includes("-->")) inComment = false;
        continue;
      }
      if (line.includes("<!--") && !line.includes("-->")) { inComment = true; continue; }

      const a = line.replace(/\s+$/, "");
      const b = lines[i + 1].trim();
      if (!a || !b) continue;
      const last = [...a].pop();
      const next = [...b][0];
      if (!nonLatin(last) || !nonLatin(next)) continue;
      checked += 1;
      assert(false,
        name + ".html line " + (i + 1) + " ends with a non-Latin character and " +
        "line " + (i + 2) + " begins with one, so the newline renders as a SPACE " +
        "inside the sentence: ..." + a.slice(-12) + " | " + b.slice(0, 12) + "... " +
        "Put the sentence on one source line.");
    }
  }
  eq(checked, 0, "unreachable: the loop asserts before it counts");
});

// AND THE SCAN HAS TO BE ABLE TO SEE THE FAULT. The guard above is an absence,
// and an absence passes just as happily when the thing doing the looking is
// broken — a regex that matched nothing, a page list that loaded nothing. So the
// same predicate is run against a string that DOES have the fault.
test("seo: the Chinese line-break scan can actually detect one", () => {
  const broken = ["  <p>這裡的每一夜，都先在伺服器上", "  重跑過一遍。</p>"];
  const a = broken[0].replace(/\s+$/, "");
  const b = broken[1].trim();
  assert(nonLatin([...a].pop()) && nonLatin([...b][0]),
    "the predicate does not fire on a known-broken pair, so the guard above " +
    "proves nothing about the pages it scanned");
  // And it leaves a Chinese-to-Latin break alone, which is correct spacing.
  const fine = ["  <p>需要", "  JavaScript。</p>"];
  assert(!(nonLatin([...fine[0].replace(/\s+$/, "")].pop()) && nonLatin([...fine[1].trim()][0])),
    "the predicate fires on 需要/JavaScript, which renders with the space Chinese " +
    "typography actually wants");
  assert(PUBLIC_PAGES.length > 0 && html[PUBLIC_PAGES[0]].length > 100,
    "no page source was loaded, so the scan above walked nothing");
});

test("seo: every public page has a title and a description", () => {
  for (const name of PUBLIC_PAGES) {
    const title = tag(html[name], /<title>(.*?)<\/title>/);
    assert(title && title.length > 10, `${name} has a real title`);
    const desc = meta(html[name], "description");
    assert(desc && desc.length > 50, `${name} has a real description`);
    // Past roughly 160 characters a result snippet is cut mid-sentence, which
    // is worse than a shorter one that ends where it meant to.
    assert(desc.length <= 165, `${name} description fits a snippet (${desc.length})`);
  }
});

test("seo: no two pages claim the same title", () => {
  const titles = PUBLIC_PAGES.map((n) => tag(html[n], /<title>(.*?)<\/title>/));
  eq(new Set(titles).size, titles.length, "duplicate titles compete with each other");
});

test("seo: every page canonicalises to itself", () => {
  for (const name of PUBLIC_PAGES) {
    const canonical = tag(html[name], /rel="canonical" href="([^"]*)"/);
    assert(canonical, `${name} has a canonical`);
    const expected = name === "index" ? ROOT : ROOT + name;
    eq(canonical, expected, `${name} canonical`);
  }
});

// The one that had already gone wrong.
test("seo: the sitemap lists exactly the pages that exist", () => {
  const listed = PAGES.map((p) => ROOT + p).sort();
  const claimed = PUBLIC_PAGES.map((n) => tag(html[n], /rel="canonical" href="([^"]*)"/)).sort();
  eq(listed, claimed, "sitemap and canonicals must be the same set");
});

test("seo: og:url agrees with the canonical", () => {
  for (const name of PUBLIC_PAGES) {
    const canonical = tag(html[name], /rel="canonical" href="([^"]*)"/);
    const og = tag(html[name], /property="og:url" content="([^"]*)"/);
    eq(og, canonical, `${name} og:url`);
  }
});

test("seo: the social card is an absolute URL on every page", () => {
  for (const name of PUBLIC_PAGES) {
    const img = tag(html[name], /property="og:image" content="([^"]*)"/);
    assert(img && img.startsWith("https://"), `${name} og:image is absolute`);
    assert(tag(html[name], /property="og:image:alt" content="([^"]*)"/), `${name} og:image:alt`);
  }
});

test("seo: structured data parses", () => {
  for (const name of PUBLIC_PAGES) {
    const blocks = html[name].match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g) || [];
    assert(blocks.length > 0, `${name} has structured data`);
    for (const block of blocks) {
      const json = block.replace(/<\/?script[^>]*>/g, "");
      const parsed = JSON.parse(json); // throws, which is the assertion
      assert(parsed["@context"] === "https://schema.org", `${name} names the vocabulary`);
      assert(parsed["@type"], `${name} names a type`);
    }
  }
});

// A FALSE STATEMENT PARSES PERFECTLY, which is why the test above did not catch
// this. "seo: structured data parses" asserts the JSON is well-formed and names
// a vocabulary; it has no opinion about whether any of it is true. inLanguage
// said "en" while the game had been fully playable in 繁體中文 at that URL for
// weeks — and with DETECT on since 2026-08-24 a Chinese browser is SENT to the
// Chinese version of a page whose own metadata calls itself English.
//
// DERIVED FROM js/lang.js, and the tag comes from there too rather than being
// spelled here. LANGS carries "zh-Hant-TW", which is also what stampDocument
// writes into <html lang>, so the page and its structured data make the same
// claim in the same words. A third language then fails this guard on the day it
// is added instead of quietly leaving the metadata a language short.
test("seo: the structured data names every language the site ships", () => {
  const tags = Object.values(LANGS).map((l) => l.tag);
  assert(tags.length >= 2,
    "js/lang.js exports fewer than two languages, so this guard is comparing " +
    "against nothing — if the site is monolingual again, delete it");

  const blocks = html.index.match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g) || [];
  const games = blocks
    .map((b) => JSON.parse(b.replace(/<\/?script[^>]*>/g, "")))
    .filter((p) => p["@type"] === "VideoGame");
  eq(games.length, 1, "the landing page does not carry exactly one VideoGame block");

  const declared = [].concat(games[0].inLanguage || []);
  for (const t of tags) {
    assert(declared.indexOf(t) !== -1,
      "the VideoGame block does not name " + t + " in inLanguage (it says " +
      JSON.stringify(games[0].inLanguage) + "), so the page understates what it " +
      "is — js/lang.js ships that language and a browser asking for it is sent here");
  }
  for (const t of declared) {
    assert(tags.indexOf(t) !== -1,
      "inLanguage claims " + t + ", which js/lang.js does not ship — the page " +
      "is promising a language a reader cannot get");
  }
});

// THE ROOMS ARE IN THE SERVED MARKUP (#134).
//
// tiles.html used to ship 315 indexable characters: a heading, two intro
// paragraphs and two placeholders. Twenty rooms with names, in two languages,
// were all injected at load — so the most distinctive vocabulary the game owns
// existed nowhere a crawler or a reader without script could see it.
// tools/render_tiles.py writes the words in ahead of time; this checks they
// arrived and, more importantly, that they still MATCH.
//
// READ FROM theme.json, NEVER LISTED HERE. A guard with its own copy of the
// twenty names is a guard testing its own copy — it passes while the page and
// the data disagree, which is the drift the whole page exists to prevent. That
// drift is not hypothetical here: the intro read "sixteen rooms" for a while
// after the set had become twenty.
test("seo: the tiles page serves every room name, from the data (#134)", async () => {
  const [tiles, theme] = await Promise.all([
    fresh("../data/tiles.json").then((r) => r.json()),
    fresh("../data/theme.json").then((r) => r.json()),
  ]);
  const defs = [].concat(tiles.indoor || [], tiles.outdoor || []);
  const names = defs.map((d) => (theme.tiles || {})[d.id]).filter(Boolean);

  // 1. COUNT FIRST, so nothing below can pass on an empty haystack. "every name
  //    is present" is trivially true of no names at all.
  eq(defs.length, 20, "the tile set is no longer twenty tiles (" + defs.length + ")");
  eq(names.length, 20,
    "only " + names.length + " of the twenty tiles have a name in theme.json, so " +
    "this guard would be checking a short list against the page");

  // 2. Strip what a crawler does not read, so a name surviving only inside a
  //    comment or a <script> does not count as served.
  const served = html.tiles
    .replace(/<script[\s\S]*?<\/script>/g, " ")
    .replace(/<!--[\s\S]*?-->/g, " ");

  const missing = names.filter((n) => served.indexOf(n) === -1);
  eq(missing.length, 0,
    "tiles.html does not serve " + missing.length + " of the twenty room names — " +
    missing.join(", ") + ". Re-run: python tools/render_tiles.py");

  // 3. AND THE COUNT IN THE PROSE IS THE REAL ONE. This is the specific drift
  //    the intro was made dynamic for, so a pre-rendered page has to be held to
  //    it too — a build step that is not re-run is exactly how "sixteen" got
  //    there the first time.
  const words = ((theme.tilesPage || {}).words) || [];
  const spelled = words[defs.length];
  assert(spelled,
    "theme.json cannot spell " + defs.length + ", so the intro cannot be checked");
  const intro = /<p class="muted" id="tile-intro">([\s\S]*?)<\/p>/.exec(served);
  assert(intro, "tiles.html has no intro paragraph to check");
  assert(new RegExp(spelled, "i").test(intro[1]),
    "the served intro does not say " + spelled + " — it reads " +
    JSON.stringify(intro[1].trim().slice(0, 60)) + ". The tile set changed and " +
    "tools/render_tiles.py was not re-run, which is the drift this page exists " +
    "to prevent");
});

// THE BUILD'S OUTPUT AGAINST THE PAGE'S OWN (#136).
//
// tools/render_tiles.py carries a PORT of js/tilewords.js, because the build
// cannot run the real thing: there is no JS runtime here — no node, bun, deno
// or npx, no package.json, no CI. A port is two implementations of ten
// branches, and two implementations drift. This is the check that makes that
// safe, and it is the whole reason porting was the right choice rather than a
// resigned one.
//
// IT COMPARES AGAINST tileWords() RUN LIVE, never against a list written here.
// A hand-written expectation is a third implementation, and it agrees with
// whichever of the other two it was copied from on the day it was copied —
// which is precisely the drift being prevented.
test("seo: the pre-rendered tile words match what the page composes (#136)", async () => {
  const [tiles, theme] = await Promise.all([
    fresh("../data/tiles.json").then((r) => r.json()),
    fresh("../data/theme.json").then((r) => r.json()),
  ]);

  const unesc = (t) => t.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
  // What the served page actually carries, per <li>.
  const items = [...html.tiles.matchAll(/<li>([\s\S]*?)<\/li>/g)].map((m) => {
    const block = m[1];
    const h3 = /<h3>([\s\S]*?)<\/h3>/.exec(block);
    const ps = [...block.matchAll(/<p>([\s\S]*?)<\/p>/g)].map((x) => unesc(x[1].trim()));
    return { name: h3 ? unesc(h3[1].trim()) : null, ps };
  });

  // 1. PROVE THE REGION. Every comparison below is "for each served item", and
  //    a page that renders no items satisfies all of them.
  const defs = [].concat(
    (tiles.indoor || []).map((d) => [d, "indoor"]),
    (tiles.outdoor || []).map((d) => [d, "outdoor"]));
  eq(defs.length, 20, "the tile set is no longer twenty tiles");
  eq(items.length, 20,
    "tiles.html serves " + items.length + " tile entries, not twenty — the " +
    "build did not run, or it no longer emits one <li> per tile. Re-run: " +
    "python tools/render_tiles.py");

  // 2. EVERY TILE, FIELD BY FIELD, AGAINST THE REAL COMPOSITION.
  for (const [i, [def, world]] of defs.entries()) {
    const want = tileWords(def, world, theme);
    const got = items[i];
    const expected = [want.doors]
      .concat(want.chips.length ? [want.chips.join(" · ")] : [])
      .concat(want.notes);

    eq(got.name, want.name,
      "tile " + i + " (" + def.id + ") is served as " + JSON.stringify(got.name) +
      " and the page composes " + JSON.stringify(want.name));
    eq(got.ps.join(" ¶ "), expected.join(" ¶ "),
      "the served words for " + def.id + " are stale — the build and the page " +
      "disagree.\n  served: " + JSON.stringify(got.ps) +
      "\n  page:   " + JSON.stringify(expected) +
      "\nRe-run: python tools/render_tiles.py");
  }
});

test("seo: every page can be reached from every other", () => {
  for (const name of PUBLIC_PAGES) {
    // The menu is the hub, so it is the one link every page must carry.
    assert(/href="index\.html"/.test(html[name]) || name === "index", `${name} links home`);
  }
  for (const name of PUBLIC_PAGES.filter((n) => n !== "index")) {
    assert(/href="[a-z]+\.html"/.test(html.index), "the menu links out");
  }
});

// The noindex has two failure modes and they point opposite ways, so one
// assertion cannot cover both: shipping WITH it leaves the game unfindable,
// and losing it BEFORE shipping puts a duplicate of Grave Errand's copy in
// front of the real game. Which bug is live depends only on whether the site
// has shipped, so the flag decides which way the test reads.
//
// This used to assert the post-ship half unconditionally, and failed by design
// for weeks. A suite with a permanent red teaches everyone to skim past red,
// which costs more than the check was worth — and it very nearly did: a stale
// two-test-short run went unquestioned on the same suite because one number
// among the noise looked normal.
test("seo: every public page's noindex matches the ship state", () => {
  for (const name of PUBLIC_PAGES) {
    const robots = meta(html[name], "robots") || "";
    const heldBack = /noindex/.test(robots);
    if (SHIPPED) {
      assert(!heldBack, `${name} still carries a noindex — the shipped site is invisible`);
    } else {
      assert(heldBack, `${name} has lost its noindex before ship — it will be indexed as a duplicate`);
    }
  }
});

// ---- The measurement tag -------------------------------------------------------
// Not SEO, but the same failure shape as everything above and it belongs with
// them: five hand-pasted copies of one hardcoded id, invisible when wrong. The
// sitemap already proved this project can ship four pages out of five and not
// notice.
const GA_ID = "G-Q4VS3P3T58";

test("analytics: every public page carries the tag, exactly once", () => {
  for (const name of PUBLIC_PAGES) {
    const loaders = (html[name].match(/googletagmanager\.com\/gtag\/js\?id=/g) || []).length;
    eq(loaders, 1, `${name} loads gtag once — twice double-counts every visit`);
    assert(html[name].includes(`gtag('config', '${GA_ID}')`), `${name} configures ${GA_ID}`);
  }
});

test("analytics: one property, not five", () => {
  const ids = PUBLIC_PAGES.flatMap((n) => html[n].match(/G-[A-Z0-9]+/g) || []);
  eq([...new Set(ids)], [GA_ID], "a stray id sends part of the traffic somewhere else");
});
